#!/usr/bin/env bash
# Commit a bot's work and push it, rebuilding generated files on top of the
# latest branch tip on every attempt instead of rebasing them.
#
# WHY
# ---
# On 2026-11-04 the scheduled price refresh (delayed by GitHub from 07:17 to
# 15:27 UTC) edited site/sitemap.xml 14 s before a merge that edited the same
# lines. Its `git pull --rebase` hit a content conflict, and the retry loop
# could not recover: a rebase stopped mid-conflict makes every later pull
# fail with "you have unmerged files". The day's prices were never committed.
#
# Generated files must never be merged. They are a function of their inputs,
# so the correct resolution of any conflict in them is simply to run the
# generator again on the newer inputs. This script:
#
#   1. commits DATA paths (real inputs, e.g. the fetched price JSON) - these
#      are rebased, and a conflict in them is a genuine problem: the rebase
#      is aborted and the job fails loudly;
#   2. throws away every other uncommitted change (it is all regenerable);
#   3. per attempt: fetch, rebase the data commit onto the tip, run REGEN,
#      commit DERIVED paths, push. If the push is rejected (the branch moved
#      again), the derived commit is dropped and the next attempt rebuilds it.
#
# Usage:
#   push-with-regenerate.sh "<commit message>" "<data paths>" "<derived paths>" "<regen command>"
# Paths are space-separated; either list may be empty. REGEN runs via bash -c.
# Needs GITHUB_REF_NAME (set by Actions); falls back to the current branch.
set -uo pipefail

msg="$1"; data_paths="$2"; derived_paths="$3"; regen="$4"
ref="${GITHUB_REF_NAME:-$(git rev-parse --abbrev-ref HEAD)}"
attempts="${PUSH_ATTEMPTS:-3}"

git config user.name  "egybi-data-bot"
git config user.email "41898282+github-actions[bot]@users.noreply.github.com"

# shellcheck disable=SC2086  # the path lists are deliberately word-split
if [ -n "$data_paths" ] && [ -n "$(git status --porcelain -- $data_paths)" ]; then
  git add -- $data_paths
  git commit -q -m "$msg" || { echo "::error::could not commit data"; exit 1; }
  echo "data committed: $(git log -1 --format=%h)"
fi

# Everything still uncommitted was generated by this run and is rebuilt below.
git reset -q --hard HEAD

for attempt in $(seq 1 "$attempts"); do
  if ! git fetch -q origin "$ref"; then
    echo "attempt $attempt: fetch failed; retrying in 5s"; sleep 5; continue
  fi
  if ! git rebase -q "origin/$ref"; then
    git rebase --abort
    echo "::error::the DATA commit conflicts with origin/$ref - a real conflict in an input file, not resolved automatically"
    exit 1
  fi

  if ! bash -c "$regen"; then
    echo "::error::regeneration failed on top of origin/$ref"; exit 1
  fi

  made_derived=0
  # shellcheck disable=SC2086
  if [ -n "$derived_paths" ] && [ -n "$(git status --porcelain -- $derived_paths)" ]; then
    git add -- $derived_paths
    git commit -q -m "$msg (regenerated)" && made_derived=1
  fi
  git reset -q --hard HEAD   # anything the generator wrote outside DERIVED

  if [ "$(git rev-list --count "origin/$ref..HEAD")" -eq 0 ]; then
    echo "nothing to push: origin/$ref already holds this content"; exit 0
  fi
  ahead="$(git rev-list --count "origin/$ref..HEAD")"
  if git push -q origin "HEAD:$ref"; then
    echo "pushed on attempt $attempt ($ahead commit(s))"
    exit 0
  fi

  echo "attempt $attempt: push rejected (the branch moved); rebuilding on the new tip in 5s"
  if [ "$made_derived" = 1 ]; then git reset -q --hard HEAD~1; fi
  sleep 5
done
echo "::error::could not push after $attempts attempts"
exit 1
